    "front": "Comment ponctue-t-on une énumération verticale à puces ou tirets en typographie soignée ?",
    "back": "Chaque item commence par une minuscule et se termine par un point-virgule ; le dernier item se termine par un point | Ex : Il faut : - lire ; - écrire ; - réviser.",
