    "front": "Complète : Devant la conjonction 'mais', la virgule est {{c1::obligatoire}} pour marquer l'opposition.",
    "back": "obligatoire | Règle : 'Mais' introduisant une clause coordonnée adversative doit être précédé d'une virgule | Ex : Il a cherché partout, mais n'a rien trouvé.",
