    "back": "anglais \" \" | Règle : Pour citer un texte à l'intérieur d'une citation déjà ouverte en « », on emploie les guillemets anglais \"...\" sans espace | Ex : « Il m'a dit : \"Attends-moi\", puis il est parti. »",
