    "front": "Quelle est l'erreur dans : 'Je vous prie d'agréer l'expression de mes sentiments distingués' adressé à une autorité féminine ?",
    "back": "Une femme écrivant à un homme ou un homme à une femme de haute hiérarchie préfère souvent 'l'assurance de ma parfaite considération' ou 'de mon profond respect' pour éviter l'ambiguïté affective du mot 'sentiments'.",
